/* =================================================================
   INSTRUMENTS ET MISSIONS — page « Mission et instruments » de chaque sonde (schéma d'Observatories v1.0, src/data-inst.js
   et src/data-mission.js, simplifié). Chaque texte est donné en français et en anglais : L(fr, en).
   INST_DATA[id] = { summary, refs:{clé:{t,p,u}}, archives:[{label, desc, url}], instruments:[{
       id, name, full, type (TYPES), use, summary, bands:[{l, lo, hi}] (µm ; radio comprise), specs:[[libellé, valeur, clé(s) de source]],
       stac (préfixe des collections STAC-PLANET de l'instrument, data-stac.js), docs:[{l, u}] }] }
   Les clés de source renvoient aux refs de la mission (data-missions.js) ou à celles d'ici. Règle 1 : chaque valeur chiffrée cite sa source.
   Les fiches d'expérience de la NSSDCA et les dossiers de presse ont été relevés par tools/probe/probe_sources.py (23 novembre 2026).
================================================================= */
function L(fr, en){ return OBS_LANG === 'en' ? en : fr; }
var INST_TYPES = {
  cam:   { c:'#2F6FE4', l:L('Caméra', 'Camera') },
  spec:  { c:'#C0398A', l:L('Spectromètre', 'Spectrometer') },
  radar: { c:'#B86A00', l:L('Radar', 'Radar') },
  alt:   { c:'#0F8A7A', l:L('Altimètre laser', 'Laser altimeter') },
  rad:   { c:'#C2452D', l:L('Radiomètre', 'Radiometer') },
  part:  { c:'#6B55C9', l:L('Particules et champs', 'Particles and fields') },
  radio: { c:'#5B6770', l:L('Radioscience', 'Radio science') }
};
function nssdcExp(cospar, n, title){ return { t:L('Fiche d\'expérience NSSDCA : ', 'NSSDCA experiment page: ') + title, p:'NASA NSSDCA', u:'https://nssdc.gsfc.nasa.gov/nmc/experiment/display.action?id=' + cospar + '-' + n }; }
var PDS_GEO = { label:'PDS Geosciences Node, Orbital Data Explorer', desc:L('Archive de la NASA d\'où viennent les collections ode-* de STAC-PLANET', 'NASA archive behind the ode-* collections of STAC-PLANET'), url:'https://ode.rsl.wustl.edu/' };
var STACP = { label:'STAC-PLANET (PDSSP, CNES)', desc:L('Catalogue STAC des données planétaires, interrogé par ce site', 'STAC catalogue of planetary data, queried by this site'), url:'https://stacplanet.pdssp.eu/' };

